
(function () {
  'use strict';

  function initClosingAscii() {
    if (window.innerWidth < 1024) return;

    var section = document.getElementById('closing-cta');
    if (!section) return;

    var canvas = document.getElementById('closing-ascii-canvas');
    if (window.innerWidth < 1024) {
      if (canvas) canvas.remove();
      return;
    }

    if (!canvas) {
      canvas = document.createElement('canvas');
      canvas.className = 'closing-ascii-canvas';
      canvas.id = 'closing-ascii-canvas';
      canvas.setAttribute('aria-hidden', 'true');
      section.insertBefore(canvas, section.firstChild);
    }

    var motionQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
    var isReduced = Boolean(motionQuery && motionQuery.matches);

    var ctx = canvas.getContext('2d', { alpha: true });
    if (!ctx) return;

    var dpr = Math.min(window.devicePixelRatio || 1, 2);
    var width = 0;
    var height = 0;
    var cellW = 16;
    var cellH = 20;
    var cells = [];
    var avoidRects = [];
    var rafId = null;
    var isIntersecting = false;
    var lastFrameTime = 0;
    var FPS_INTERVAL = 1000 / 30; // 30fps cap (~33.3ms)

    var chars = ['₹', '$', '0', '1', '+', ':', '·'];

    var mouseX = -9999;
    var mouseY = -9999;
    var mouseActive = false;
    var CURSOR_RADIUS = 140;

    var atlas = Object.create(null);
    function getGlyphTile(ch) {
      if (atlas[ch]) return atlas[ch];
      var tile = document.createElement('canvas');
      var tileDpr = 2;
      tile.width = 24 * tileDpr;
      tile.height = 24 * tileDpr;
      var tctx = tile.getContext('2d');
      tctx.scale(tileDpr, tileDpr);
      tctx.font = '12px "Geist Mono", monospace';
      tctx.textAlign = 'center';
      tctx.textBaseline = 'middle';
      tctx.fillStyle = '#4df3e0';
      tctx.fillText(ch, 12, 12);
      atlas[ch] = tile;
      return tile;
    }
    chars.forEach(getGlyphTile);

    function computeAvoidanceRects() {
      avoidRects = [];
      var secRect = section.getBoundingClientRect();
      var targets = section.querySelectorAll('.closing-title, .closing-desc, .closing-actions, .closing-guarantee, .section-pill');
      targets.forEach(function (el) {
        var r = el.getBoundingClientRect();
        if (r.width > 0 && r.height > 0) {
          avoidRects.push({
            left: (r.left - secRect.left) - 24,
            top: (r.top - secRect.top) - 24,
            right: (r.right - secRect.left) + 24,
            bottom: (r.bottom - secRect.top) + 24
          });
        }
      });
    }

    function buildCells() {
      computeAvoidanceRects();
      cells = [];
      var cols = Math.floor(width / cellW);
      var rows = Math.floor(height / cellH);

      var leftCells = [];
      var rightCells = [];

      for (var r = 0; r < rows; r++) {
        var y = r * cellH + cellH / 2;
        for (var c = 0; c < cols; c++) {
          var x = c * cellW + cellW / 2;
          var nx = x / width;

          var isLeftColumn = nx <= 0.28;
          var isRightColumn = nx >= 0.72;
          if (!isLeftColumn && !isRightColumn) continue;

          var insideAvoid = false;
          for (var i = 0; i < avoidRects.length; i++) {
            var b = avoidRects[i];
            if (x >= b.left && x <= b.right && y >= b.top && y <= b.bottom) {
              insideAvoid = true;
              break;
            }
          }
          if (insideAvoid) continue;

          var charIdx = Math.abs((c * 5 + r * 11)) % chars.length;
          var baseBrightness = 0.22 + (Math.sin(c * 0.45 + r * 0.65) + 1) * 0.28;

          var cellObj = {
            x: x,
            y: y,
            origX: x,
            origY: y,
            char: chars[charIdx],
            baseBrightness: baseBrightness,
            phase: (c * 0.35 + r * 0.75) % (Math.PI * 2),
            curDx: 0,
            curDy: 0
          };

          if (isLeftColumn) {
            leftCells.push(cellObj);
          } else {
            rightCells.push(cellObj);
          }
        }
      }

      if (leftCells.length > 400) leftCells = leftCells.slice(0, 400);
      if (rightCells.length > 400) rightCells = rightCells.slice(0, 400);

      cells = leftCells.concat(rightCells);

      window.__LEDGIO_CLOSING_ASCII = {
        cells: cells,
        avoidRects: avoidRects,
        getCellCount: function () { return cells.length; },
        getAvoidRects: function () { return avoidRects; },
        isReduced: function () { return isReduced; }
      };
    }

    function resize() {
      if (window.innerWidth < 1024) {
        canvas.style.display = 'none';
        return;
      }
      canvas.style.display = 'block';
      var rect = section.getBoundingClientRect();
      width = section.clientWidth || rect.width;
      height = rect.height;
      canvas.width = Math.floor(width * dpr);
      canvas.height = Math.floor(height * dpr);
      canvas.style.width = width + 'px';
      canvas.style.height = height + 'px';
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      buildCells();
      renderFrame(0);
    }

    function renderFrame(time) {
      if (!ctx || width === 0 || height === 0) return;
      ctx.clearRect(0, 0, width, height);

      var t = time * 0.0016;

      for (var i = 0; i < cells.length; i++) {
        var cell = cells[i];
        var alpha = cell.baseBrightness;

        if (!isReduced) {
          alpha += Math.sin(t + cell.phase) * 0.16;

          var targetDx = 0;
          var targetDy = 0;
          if (mouseActive) {
            var dx = cell.origX - mouseX;
            var dy = cell.origY - mouseY;
            var distSq = dx * dx + dy * dy;
            if (distSq < CURSOR_RADIUS * CURSOR_RADIUS && distSq > 0) {
              var dist = Math.sqrt(distSq);
              var factor = (1 - dist / CURSOR_RADIUS);
              alpha += factor * 0.5; // Brighten near cursor
              targetDx = (dx / dist) * factor * 6;
              targetDy = (dy / dist) * factor * 6;
            }
          }

          cell.curDx += (targetDx - cell.curDx) * 0.2;
          cell.curDy += (targetDy - cell.curDy) * 0.2;
          cell.x = cell.origX + cell.curDx;
          cell.y = cell.origY + cell.curDy;
          alpha = Math.max(0.1, Math.min(0.95, alpha));
        }

        var tile = getGlyphTile(cell.char);
        ctx.globalAlpha = alpha;
        ctx.drawImage(tile, cell.x - 12, cell.y - 12, 24, 24);
      }
      ctx.globalAlpha = 1;
    }

    function loop(now) {
      if (!isIntersecting || document.hidden || isReduced) {
        rafId = null;
        return;
      }
      var elapsed = now - lastFrameTime;
      if (elapsed >= FPS_INTERVAL) {
        lastFrameTime = now - (elapsed % FPS_INTERVAL);
        renderFrame(now);
      }
      rafId = requestAnimationFrame(loop);
    }

    function startLoop() {
      if (isReduced) {
        renderFrame(0);
        return;
      }
      if (!rafId && isIntersecting && !document.hidden) {
        lastFrameTime = performance.now();
        rafId = requestAnimationFrame(loop);
      }
    }

    function stopLoop() {
      if (rafId) {
        cancelAnimationFrame(rafId);
        rafId = null;
      }
    }

    if (window.matchMedia('(hover: hover) and (pointer: fine)').matches) {
      section.addEventListener('pointermove', function (e) {
        var r = section.getBoundingClientRect();
        mouseX = e.clientX - r.left;
        mouseY = e.clientY - r.top;
        mouseActive = true;
      }, { passive: true });

      section.addEventListener('pointerleave', function () {
        mouseActive = false;
        mouseX = -9999;
        mouseY = -9999;
      }, { passive: true });
    }

    if ('IntersectionObserver' in window) {
      var obs = new IntersectionObserver(function (entries) {
        entries.forEach(function (entry) {
          isIntersecting = entry.isIntersecting;
          if (isIntersecting) {
            startLoop();
          } else {
            stopLoop();
          }
        });
      }, { threshold: 0.05 });
      obs.observe(section);
    } else {
      isIntersecting = true;
      startLoop();
    }

    document.addEventListener('visibilitychange', function () {
      if (document.hidden) {
        stopLoop();
      } else if (isIntersecting) {
        startLoop();
      }
    });

    window.addEventListener('resize', resize, { passive: true });
    resize();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initClosingAscii);
  } else {
    initClosingAscii();
  }
})();
